class UserRepository:
    def __init__(self):
        self._users = {}
        self._next_id = 1

    def add(self, username, email, password):
        uid = self._next_id
        self._next_id += 1
        self._users[uid] = {
            "id": uid,
            "username": username,
            "email": email,
            "password_hash": "hash:" + password,
        }
        return self._users[uid]

    def get(self, uid):
        return self._users.get(uid)

    def list(self):
        return list(self._users.values())

